from pathlib import Path
p=Path('ClockTimer.js')
s=p.read_text()
start=s.index('        #processElapsedOverwriteRanges(\n')
end=s.index('\n        #tick() {', start)
new='''        #processElapsedOverwriteRanges(\n            now\n        ) {\n            const ranges =\n                this.#getManagedTimeRanges()\n                    .filter(\n                        range =>\n                            range.timeRangeExiting !== true &&\n                            range.hasAttribute(\n                                "overwrite"\n                            )\n                    );\n\n            for (const range of ranges) {\n                const end =\n                    Number(\n                        range.clockTimerEnd\n                    );\n\n                if (\n                    !Number.isFinite(end) ||\n                    now < end\n                ) {\n                    continue;\n                }\n\n                const overwriteType =\n                    range.getAttribute(\n                        "overwrite"\n                    )?.trim();\n\n                range.removeAttribute(\n                    "overwrite"\n                );\n\n                if (!overwriteType) {\n                    continue;\n                }\n\n                const hasAdjacentRange =\n                    this.#getManagedTimeRanges()\n                        .some(\n                            candidate =>\n                                candidate !== range &&\n                                candidate.timeRangeExiting !== true &&\n                                candidate.getAttribute(\n                                    "type"\n                                ) !== "elapsed" &&\n                                Number(\n                                    candidate.clockTimerStart\n                                ) === end\n                        );\n\n                if (!hasAdjacentRange) {\n                    continue;\n                }\n\n                this.overwrite({\n                    type: overwriteType\n                });\n            }\n        }\n'''
s=s[:start]+new+s[end:]
p.write_text(s)
